This function in C++ is for checking if a number is prime or not. Can you create a driver/main function that will use it and print to the console the first 20 prime numbers?

using namespace std;

bool isPrime(int n)
{
      if(n == 1 || n == 0) return false;

      for(int i = 2; i < n; i++)
      {
        if(n % i == 0) return false;
      }
      return true;
}

```cpp
#include <iostream>
using namespace std;

bool isPrime(int n)
{
    if(n == 1 || n == 0) return false;

    for(int i = 2; i < n; i++)
    {
        if(n % i == 0) return false;
    }
    return true;
}

int main() {
    int count = 0;
    int num = 2;

    while (count < 20) {
        if (isPrime(num)) {
            cout << num << " ";
            count++;
        }
        num++;
    }
    cout << endl;

    return 0;
}
